import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Browser Use и Computer Use","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/browser-computer-use.md","filePath":"ru/guides/browser-computer-use.md","lastUpdated":1792323081000}'),d={name:"ru/guides/browser-computer-use.md"};function s(c,e,l,i,h,n){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="browser-use-и-computer-use" tabindex="-1">Browser Use и Computer Use <a class="header-anchor" href="#browser-use-и-computer-use" aria-label="Permalink to &quot;Browser Use и Computer Use&quot;">​</a></h1><p>Memoh может дать Bot видимый рабочий стол и браузер с графическим интерфейсом (headed) внутри контейнера его рабочего пространства. Это не то же самое, что запуск headless-скрипта Playwright: Bot изучает и оперирует тем же графическим браузером, который вы видите в панели <strong>Desktop</strong> приложения.</p><h2 id="понятия" tabindex="-1">Понятия <a class="header-anchor" href="#понятия" aria-label="Permalink to &quot;Понятия&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Возможность</th><th>Для чего подходит</th><th>Как работает</th></tr></thead><tbody><tr><td>Headless-команды браузера</td><td>Быстрая скриптовая автоматизация внутри рабочего пространства</td><td>Запуск Playwright и других браузерных инструментов как обычных команд рабочего пространства.</td></tr><tr><td>Browser Use</td><td>Веб-страницы, формы, навигация, скриншоты, проверка дерева доступности</td><td>Оперирует headed-экземпляром Chrome/Chromium рабочего пространства через CDP.</td></tr><tr><td>Computer Use</td><td>Нативные диалоги, сломанное состояние браузера, GUI вне браузера</td><td>Читает дерево доступности рабочего стола (AT-SPI) и получает ref-ссылки; когда механизм доступности недоступен, переходит на координаты и скриншоты.</td></tr></tbody></table><p>Для веб-страниц предпочитайте Browser Use. Берите Computer Use, когда задача зависит от состояния GUI, до которого CDP не дотягивается.</p><h2 id="дисплеи-рабочего-пространства-и-vnc" tabindex="-1">Дисплей рабочего пространства и VNC <a class="header-anchor" href="#дисплеи-рабочего-пространства-и-vnc" aria-label="Permalink to &quot;Дисплей рабочего пространства и VNC&quot;">​</a></h2><p>Дисплей рабочего пространства — это окружение рабочего стола внутри контейнера рабочего пространства Bot. VNC/RFB — транспорт изображения и ввода, стоящий за этим рабочим столом, а сеанс рабочего стола в приложении использует WebRTC.</p><p>Главная ценность не в VNC как таковом. Важно то, что рабочее пространство может запускать headed Chrome/Chromium для сайтов и процедур входа, которые плохо работают в headless-режиме.</p><h2 id="подготовка-рабочего-стола-bot" tabindex="-1">Подготовка рабочего стола Bot <a class="header-anchor" href="#подготовка-рабочего-стола-bot" aria-label="Permalink to &quot;Подготовка рабочего стола Bot&quot;">​</a></h2><ol><li>Откройте страницу Bot.</li><li>Перейдите на вкладку <strong>Desktop</strong>.</li><li>Подготовьте или включите среду выполнения дисплея рабочего пространства.</li><li>Откройте сеанс дисплея со страницы настроек Bot или из чат-пространства.</li></ol><p>Среда выполнения дисплея устанавливает или использует рабочий стол, VNC-сервер, браузер и шрифты, нужные для видимого сеанса. Доступность зависит от бэкенда рабочего пространства и образа.</p><h2 id="инструменты-агента" tabindex="-1">Инструменты агента <a class="header-anchor" href="#инструменты-агента" aria-label="Permalink to &quot;Инструменты агента&quot;">​</a></h2><p>Когда рабочий стол рабочего пространства включён, агент может пользоваться браузерными и «компьютерными» инструментами:</p><ul><li><code>browser_observe</code> изучает текущую страницу браузера (snapshot, get_content, screenshot, evaluate и так далее).</li><li><code>browser_action</code> щёлкает, заполняет поля, печатает, нажимает клавиши и выполняет переходы в headed-браузере.</li><li><code>browser_remote_session</code> открывает CDP-эндпоинт браузера для сессий, управляемых кодом.</li><li><code>computer_observe</code> возвращает снимок дерева доступности рабочего стола (ref-ссылки вроде <code>e3</code>) или путь к сохранённому скриншоту.</li><li><code>computer_action</code> управляет рабочим столом. Он предпочитает <code>ref</code> из снимка и переходит на координаты <code>(x, y)</code>, когда ref недоступен или действие через доступность не удалось.</li></ul><h3 id="скриншоты-не-прикладываются-автоматически" tabindex="-1">Скриншоты не прикладываются автоматически <a class="header-anchor" href="#скриншоты-не-прикладываются-автоматически" aria-label="Permalink to &quot;Скриншоты не прикладываются автоматически&quot;">​</a></h3><p>И <code>browser_observe</code>, и <code>computer_observe</code> сохраняют скриншоты по пути в рабочем пространстве, например <code>/data/computer-screenshots/1716200000.jpg</code>, и возвращают этот путь в результате инструмента. Изображение не попадает в разговор автоматически. Когда картинка действительно нужна, прочитайте путь инструментом чтения файлов рабочего пространства: так наблюдение остаётся дешёвым, а решение, стоит ли изображение своих токенов, остаётся за моделью.</p><h3 id="помощник-доступности" tabindex="-1">Помощник доступности <a class="header-anchor" href="#помощник-доступности" aria-label="Permalink to &quot;Помощник доступности&quot;">​</a></h3><p>Computer Use зависит от бинарника <code>a11y-cli</code>, установленного в <code>/opt/memoh/toolkit/display/bin/a11y-cli</code>, и пакета <code>at-spi2-core</code> рабочего пространства. Проверка среды выполнения дисплея сообщает <code>a11y_available</code>, чтобы приложение могло показать, работоспособен ли путь доступности. Когда AT-SPI недоступен, <code>computer_action</code> продолжает работать по «сырым» координатам, а <code>computer_observe screenshot</code> остаётся пригодным.</p><p>Эти инструменты — возможности среды выполнения рабочего пространства. Они не автоматизируют само настольное приложение на Electron.</p><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="./container.html">Управление рабочим пространством Bot</a></li><li><a href="./../self-hosted/workspace-backends.html">Бэкенды рабочих пространств</a></li></ul>',21)])])}const m=o(d,[["render",s]]);export{p as __pageData,m as default};
